from pathlib import Path
import json
styles=[('空间取证','criminology-preview.html'),('黑白档案','criminology-editorial.html'),('蓝图取证','criminology-blueprint.html')]
payload=json.dumps([{'label':name,'html':(Path('assets')/f).read_text()} for name,f in styles],ensure_ascii=False).replace('<','\\u003c')
shell='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>犯罪学 / 三种风格</title><style>*{box-sizing:border-box}html,body{margin:0;height:100%;background:#080c10;color:#eee;font-family:"PingFang SC",sans-serif}body{display:flex;flex-direction:column}header{display:flex;align-items:center;justify-content:center;gap:10px;padding:12px;flex-wrap:wrap;background:#111821}header strong{font-size:14px;margin-right:12px}button{border:1px solid #465164;border-radius:8px;padding:9px 15px;background:transparent;color:#eee;cursor:pointer}button[aria-pressed=true]{background:#d8e6ed;color:#152330}small{color:#a4b1bc;font-size:11px}iframe{border:0;width:100%;flex:1;min-height:0}.quiet header{display:none}</style><body><header><strong>犯罪学 · 风格切换</strong><button data-style="0" aria-pressed="false">空间取证</button><button data-style="1" aria-pressed="false">黑白档案</button><button data-style="2" aria-pressed="false">蓝图取证</button><small id="hint">切换后停在同一时间，按播放继续</small><button id="record">进入录屏画面</button></header><iframe id="preview" title="犯罪学动画预览" allow="autoplay; fullscreen" allowfullscreen></iframe><script>
const styles=PAYLOAD,frame=document.getElementById('preview');let selected=-1,state={time:0,music:55,voice:100,musicMuted:false,voiceMuted:false},generation=0;
function capture(){try{const w=frame.contentWindow,d=w.document;if(typeof w.pause==='function')w.pause();state.time=+d.getElementById('seek').value;state.music=+d.getElementById('volume').value;state.voice=+d.getElementById('voice-volume').value;state.musicMuted=d.getElementById('music').getAttribute('aria-pressed')==='false';state.voiceMuted=d.getElementById('voice').getAttribute('aria-pressed')==='false'}catch{}}
function switchStyle(index){if(index===selected)return;if(selected>=0)capture();selected=index;const token=++generation;document.querySelectorAll('[data-style]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.style===index)));frame.onload=()=>{if(token!==generation)return;try{const w=frame.contentWindow,d=w.document;w.seek(state.time);for(const [id,value] of [['volume',state.music],['voice-volume',state.voice]]){const e=d.getElementById(id);e.value=value;e.dispatchEvent(new w.Event('input'))}if(state.musicMuted)d.getElementById('music').click();if(state.voiceMuted)d.getElementById('voice').click();d.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('quiet');d.body.classList.remove('clean')}})}catch{document.getElementById('hint').textContent='预览已加载，可按播放'}};frame.srcdoc=styles[index].html;}
document.querySelectorAll('[data-style]').forEach(b=>b.addEventListener('click',()=>switchStyle(+b.dataset.style)));
document.getElementById('record').addEventListener('click',()=>{const w=frame.contentWindow;document.body.classList.add('quiet');w.document.body.classList.add('clean');frame.focus();if(w.document.getElementById('toggle').textContent.includes('播放')||w.document.getElementById('toggle').textContent.includes('重播'))w.toggle();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('quiet')});switchStyle(2);
</script></body></html>'''
Path('assets/criminology-styles.html').write_text(shell.replace('PAYLOAD',payload))
print('Single-file style switcher:',Path('assets/criminology-styles.html').stat().st_size,'bytes')
